#include <furi.h>
#include <gui/gui.h>

/* generated by fbt from .png files in images folder */
#include <how_much_ir_icons.h>

static void input_callback(InputEvent* input, void* ctx) {
    FuriSemaphore* semaphore = ctx;

    if ((input->type == InputTypeShort) && (input->key == InputKeyBack)) {
        furi_semaphore_release(semaphore);
    }
}

static void render_callback(Canvas* canvas, void* ctx) {
    //char width_str[20];
    //char height_str[20];
    //snprintf(width_str, "%d", canvas_width(canvas));
    //snprintf(height_str, "%d", canvas_height(canvas));
    //FURI_LOG_I("HEIGHT", "%zu", canvas_height(canvas));
    //FURI_LOG_I("WIDTH", "%zu", canvas_width(canvas));
    UNUSED(ctx);
    char ir_strength[] = "hello";
    char title[] = "How Much IR?";
    int title_width = canvas_string_width(canvas, title);
    int title_x = (canvas_width(canvas) - title_width) / 2;

    canvas_draw_rframe(canvas, title_x - 5, 0, title_width + 10, 12, 3);
    canvas_draw_str(canvas, title_x, 10, title);
    canvas_draw_str(canvas, 10, 50, ir_strength);
}

int32_t howmuchir_app(void* p) {
    UNUSED(p);
    ViewPort* view_port = view_port_alloc();
    FuriSemaphore* semaphore = furi_semaphore_alloc(1, 0);
    FURI_LOG_I("HOW_MUCH_IR", "Hello world");
    FURI_LOG_I("HOW_MUCH_IR", "launching gui");
    
    view_port_draw_callback_set(view_port, render_callback, NULL);
    view_port_input_callback_set(view_port, input_callback, semaphore);
    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);
    view_port_update(view_port);
    furi_check(furi_semaphore_acquire(semaphore, FuriWaitForever) == FuriStatusOk);
    gui_remove_view_port(gui, view_port);
    view_port_free(view_port);
    furi_record_close(RECORD_GUI);
    furi_semaphore_free(semaphore);
    return 0;
}
